const steps=[
 {number:'01',label:'Choose your course',title:'Check the flow before you play.',text:'Find your course and inspect the traffic. Watching a course does not need to mean joining a round or sharing your own location.',now:'Search the four demo courses and choose Watch traffic. The moving groups are simulated.',screen:'COURSE TRAFFIC',value:'Watch the course',detail:'Four courses · mapped holes · simulated groups',action:'Watch the demo'},
 {number:'02',label:'Join your group',title:'One tee time. Everyone together.',text:'The intended product lets golfers join the group attached to their tee time. Each person chooses whether to share location. The map can focus on one representative tracker or expand the group to show participating golfers.',now:'The current demo follows a sample group. Real group invitations, tee-time membership and shared individual phone locations are not connected.',screen:'TEE TIME GROUP',value:'08:30 tee-time group',detail:'Planned: shared group with individual participants',action:'Explore the group demo'},
 {number:'03',label:'See the round',title:'Your group, with the course around it.',text:'Switch between the whole course and a selected hole. The intended live product distinguishes tee, fairway, green, waiting and uncertain tracking using course zones and recent location observations.',now:'Demo positions move along community-mapped hole routes. Tee and green progress descriptions are illustrative, not measured or confirmed GPS classifications.',screen:'LOCATION CONTEXT',value:'Tee → fairway → green',detail:'Planned: zone detection with accuracy and update age',action:'Explore the map'},
 {number:'04',label:'Keep a good pace',title:'A gentle nudge. Help when it matters.',text:'The planned workflow alerts golfers first when a sustained gap opens and they have room ahead. If spacing does not improve, staff can review the evidence and intervene. Groups waiting on traffic should not be penalized.',now:'Try traffic scenarios in a demo round. In-app alerts are scenario outputs; optional browser alerts work only while supported page execution continues. Remote push and real staff escalation are not connected.',screen:'PACE GUIDANCE',value:'Golfer first. Staff next.',detail:'Pace first · finish window next · explain the wait',action:'Try a demo round'}
];
export function aboutMarkup(){return `<div class="about-page"><section class="about-hero"><div class="about-intro"><span class="about-kicker">GOLF COURSE TRAFFIC, MADE CLEAR</span><h2>Know the flow.<br>Enjoy the round.</h2><p>Fairway Flow is a course traffic concept for golfers and the teams looking after them. Its purpose is to help groups keep pace, make finishing times more predictable, and explain the wait.</p><div class="about-actions"><a class="about-primary" href="index.html">Explore the demo ↗</a><a class="about-secondary" href="#how-the-round-works">How it works ↓</a></div><small>Four-course visual demo. Shared live phone tracking is not connected yet.</small></div><div class="about-product-preview" role="img" aria-label="Illustrative product view showing a tee-time group and traffic ahead, not live people"><div class="about-preview-top"><span>FAIRWAY FLOW</span><span>PRODUCT ILLUSTRATION</span></div><div class="about-map-pin pin-one">07</div><div class="about-map-pin pin-two">08 <small>YOUR GROUP</small></div><div class="about-preview-card"><span>THE ROUND IN CONTEXT</span><strong>Your group. The traffic ahead.</strong><p>One view for a more connected round.</p></div></div></section>
<section class="about-priorities"><div><span>01</span><strong>Keep appropriate pace.</strong><p>Know when there is room to move and when traffic is holding you up.</p></div><div><span>02</span><strong>Know when you’ll finish.</strong><p>Work toward traffic-aware finish windows, with uncertainty visible.</p></div><div><span>03</span><strong>Understand the wait.</strong><p>Give golfers context and course teams a useful reason to investigate.</p></div></section>
<section class="about-audiences"><div class="about-section-heading"><span class="about-kicker">ONE COURSE. A SHARED PICTURE.</span><h3>Built around the round,<br>and the people in it.</h3></div><div class="about-audience-grid"><article><span class="about-card-label">FOR GOLFERS</span><h4>Play together.<br>Stay in the picture.</h4><p>Join the right tee-time group. Follow your group or inspect traffic ahead. In the intended live product, participating golfers can share individual locations and see the freshness and accuracy of those readings.</p><ul><li>Watch traffic before or during a round.</li><li>Anonymous tee-time groups first; optional member detail later.</li><li>Helpful pace guidance when there is room ahead.</li></ul></article><article><span class="about-card-label">FOR COURSE TEAMS</span><h4>See a delay.<br>Understand what to do.</h4><p>The intended staff view helps course teams review growing gaps, queues and tracking issues. The goal is fewer complaints and more consistent rounds, supported by evidence about where delays begin.</p><ul><li>Review persistent issues after a golfer-first alert.</li><li>Record staff actions and whether spacing improves.</li><li>Evaluate starting intervals and recurring bottlenecks.</li></ul></article></div></section>
<section class="about-walkthrough" id="how-the-round-works"><div class="about-section-heading"><span class="about-kicker">A SIMPLE ROUND EXPERIENCE</span><h3>From checking the course<br>to keeping things moving.</h3><p>Choose a step to see the intended workflow and what the demo currently supports.</p></div><div class="about-step-buttons" role="group" aria-label="Product walkthrough">${steps.map((s,i)=>`<button data-about-step="${i}" aria-pressed="${i===0}" aria-controls="about-step-content"><span>${s.number}</span>${s.label}</button>`).join('')}</div><div id="about-step-content" aria-live="polite">${stepMarkup(0)}</div></section>
<section class="about-status-section"><div class="about-section-heading"><span class="about-kicker">WHAT EXISTS, AND WHAT COMES NEXT</span><h3>A demo you can explore.<br>A pilot we still need to prove.</h3></div><div class="about-status-grid"><article><span class="about-status ready">AVAILABLE IN THIS DEMO</span><h4>See the experience.</h4><p>Search four courses, watch simulated traffic, start a demo round, select holes and groups, explore available course previews, and try pace scenarios. Optional My GPS shows only your device location in your browser.</p></article><article><span class="about-status planned">REQUIRES A CONNECTED PILOT</span><h4>Connect real participants.</h4><p>Verified tee-time groups, individual location sharing across phones, course-scoped staff access, reliable zone classification, calibrated finish estimates, remote push, and the staff escalation workflow are not live yet.</p></article><article><span class="about-status planned">MEASURE BEFORE PROMISING</span><h4>Establish the value.</h4><p>Test location coverage, battery use, incorrect alerts, recovery after a nudge, staff workload, complaints and round-time consistency. Faster rounds and increased bookings are outcomes to validate, not guaranteed results.</p></article></div></section>
<section class="about-questions"><span class="about-kicker">CLEAR EXPECTATIONS</span><h3>A few things worth knowing.</h3><details><summary>Are the people on the demo map real?</summary><p>No. Group markers and their movement are simulated. They follow mapped hole routes to demonstrate the idea. Choosing My GPS can display your real device position locally; it is not uploaded or shared with other golfers or staff.</p></details><details><summary>Can everyone in a group share location?</summary><p>That is the intended product model: members join a verified tee-time group and individually opt in. Anonymous tee-time groups keep the course readable; a representative tracker can anchor each group. Membership, consent, aggregation and visibility rules still need implementation and pilot testing.</p></details><details><summary>Can the public see everyone’s exact position?</summary><p>The recommended production design gives public viewers overall congestion and restricts precise live positions to authorized course sessions. The final audience and identity rules need agreement with the pilot course. Anonymous markers can still identify people nearby.</p></details><details><summary>How will the app know whether someone is on a green?</summary><p>GPS alone does not reliably establish that. The live product needs mapped tee, fairway and green areas, multiple recent readings, accuracy checks and an uncertain state. Location estimates and map markers must never be used as clearance to hit.</p></details><details><summary>What about notifications, previews and rewards?</summary><p>Course previews are separate from the active traffic experience. The demo has in-app scenario alerts and optional browser alerts; background push is not connected. Course rewards remain a concept, and no money, badges or tokens are issued by completing a demo round.</p></details></section>
<section class="about-ending"><div><span class="about-kicker">TRY THE IDEA IN MOTION</span><h3>See the course.<br>Understand the traffic.</h3></div><div><a class="about-primary" href="index.html">Choose a demo course ↗</a><p>Watch first. Start a demo round when you’re ready.</p></div></section></div>`;}
function stepMarkup(index){const s=steps[index];return `<div class="about-step-copy"><span class="about-kicker">STEP ${s.number}</span><h4>${s.title}</h4><p>${s.text}</p><div class="about-try"><strong>WHAT YOU CAN TRY TODAY</strong><p>${s.now}</p></div><a class="about-primary" href="index.html">${s.action} ↗</a></div><div class="about-step-preview"><span>INTENDED PRODUCT FLOW</span><div class="about-preview-label">${s.screen}</div><strong>${s.value}</strong><p>${s.detail}</p><div class="about-flow"><span>Golfers</span><i>↔</i><span>Group</span><i>↔</i><span>Course team</span></div><small>Illustration of the product model, not a live connected session.</small></div>`;}
export function handleAboutStep(button,root){const index=Number(button.dataset.aboutStep);if(!Number.isInteger(index)||index<0||index>=steps.length)return;root.querySelectorAll('[data-about-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.aboutStep)===index)));const content=root.querySelector('#about-step-content');if(content)content.innerHTML=stepMarkup(index);}
export function aboutTeaser(){return `<section class="flight-about-section"><span class="about-kicker">GOLF COURSE TRAFFIC, MADE CLEAR</span><h2>Know the flow.<br>Enjoy the round.</h2><p>Meet the traffic concept for golfers and course teams: keeping pace first, more predictable finishes next.</p><a class="about-primary" href="about.html">How Fairway Flow works ↗</a><small>Visual demo · shared live tracking is not connected</small></section>`;}
